1	import { type ClassValue, clsx } from "clsx";
2	import { twMerge } from "tailwind-merge";
3	
4	/** Merge Tailwind classes with correct override precedence. */
5	export function cn(...inputs: ClassValue[]) {
6	  return twMerge(clsx(inputs));
7	}
