import type { ReactNode } from "react";
import { Container } from "@/components/ui/container";

type HeroProps = {
  /** Small pill badge above the headline. */
  badge?: ReactNode;
  /** Main headline. Use a highlighted `<span className="text-gradient">` for emphasis. */
  title: ReactNode;
  subtitle?: ReactNode;
  /** CTA buttons / links, rendered in a responsive row. */
  actions?: ReactNode;
  /** Small line of text below the CTAs (e.g. "Trusted by modern B2B teams"). */
  footnote?: ReactNode;
  /** Extra content rendered below the copy block (e.g. a preview card). */
  children?: ReactNode;
  /** `dark` = navy hero with light text (uses `.hero-clouds`). `light` = airy white. */
  tone?: "dark" | "light";
  /** Center or left-align the copy. */
  align?: "center" | "left";
};

/** Reusable marketing hero. On the navy tone it renders the `.hero-clouds` backdrop. */
export function Hero({
  badge,
  title,
  subtitle,
  actions,
  footnote,
  children,
  tone = "dark",
  align = "center",
}: HeroProps) {
  const dark = tone === "dark";
  const centered = align === "center";

  return (
    <section
      className={
        dark
          ? "hero-clouds relative overflow-hidden text-white"
          : "relative overflow-hidden bg-white text-foreground"
      }
    >
      {/* subtle grain/dot texture layer for depth */}
      <div
        aria-hidden
        className={
          dark
            ? "pointer-events-none absolute inset-0 opacity-[0.06] bg-dotgrid"
            : "pointer-events-none absolute inset-0 opacity-40 bg-dotgrid [mask-image:radial-gradient(60%_60%_at_50%_0%,black,transparent)]"
        }
      />
      <Container className="relative pb-20 pt-28 sm:pb-24 sm:pt-36">
        <div
          className={
            centered
              ? "mx-auto flex max-w-3xl flex-col items-center text-center"
              : "flex max-w-3xl flex-col items-start text-left"
          }
        >
          {badge && (
            <div
              className={
                dark
                  ? "inline-flex items-center gap-2 rounded-full border border-white/20 bg-white/10 px-3.5 py-1.5 text-xs font-medium text-white/90 backdrop-blur"
                  : "inline-flex items-center gap-2 rounded-full border border-border bg-muted px-3.5 py-1.5 text-xs font-medium text-muted-foreground"
              }
            >
              {badge}
            </div>
          )}

          <h1
            className={
              "mt-6 text-balance text-4xl font-extrabold leading-[1.05] tracking-tight sm:text-5xl lg:text-6xl"
            }
          >
            {title}
          </h1>

          {subtitle && (
            <p
              className={
                dark
                  ? "mt-6 max-w-2xl text-pretty text-lg text-white/70 sm:text-xl"
                  : "mt-6 max-w-2xl text-pretty text-lg text-muted-foreground sm:text-xl"
              }
            >
              {subtitle}
            </p>
          )}

          {actions && (
            <div
              className={
                centered
                  ? "mt-9 flex flex-col items-center gap-3 sm:flex-row"
                  : "mt-9 flex flex-col gap-3 sm:flex-row"
              }
            >
              {actions}
            </div>
          )}

          {footnote && (
            <p
              className={
                dark
                  ? "mt-6 text-sm text-white/50"
                  : "mt-6 text-sm text-muted-foreground"
              }
            >
              {footnote}
            </p>
          )}
        </div>

        {children && <div className="mt-16">{children}</div>}
      </Container>
    </section>
  );
}

import { Container } from "@/components/ui/container";

const DEFAULT_LOGOS = [
  "lemlist",
  "La Growth Machine",
  "gojiberry",
  "Attio",
  "Pennylane",
  "Aircall",
  "Spendesk",
  "Qonto",
];

type LogoCloudProps = {
  label?: string;
  logos?: string[];
  /** `dark` renders muted white text over a navy hero; `light` for white sections. */
  tone?: "dark" | "light";
};

/**
 * A row of "trusted by" brand wordmarks rendered as styled text (no real
 * trademarks/assets). Used on the homepage below the hero.
 */
export function LogoCloud({
  label = "Trusted by modern B2B teams",
  logos = DEFAULT_LOGOS,
  tone = "light",
}: LogoCloudProps) {
  const dark = tone === "dark";
  return (
    <section className={dark ? "" : "border-y border-border bg-muted/30 py-12"}>
      <Container>
        {label && (
          <p
            className={
              dark
                ? "text-center text-xs font-semibold uppercase tracking-widest text-white/50"
                : "text-center text-xs font-semibold uppercase tracking-widest text-muted-foreground"
            }
          >
            {label}
          </p>
        )}
        <div className="mt-7 flex flex-wrap items-center justify-center gap-x-10 gap-y-6">
          {logos.map((logo) => (
            <span
              key={logo}
              className={
                dark
                  ? "text-lg font-bold tracking-tight text-white/70 transition-colors hover:text-white"
                  : "text-lg font-bold tracking-tight text-foreground/45 transition-colors hover:text-foreground/80"
              }
            >
              {logo}
            </span>
          ))}
        </div>
      </Container>
    </section>
  );
}

import { Container } from "@/components/ui/container";

type Stat = { value: string; label: string };

type StatStripProps = {
  stats: Stat[];
  /** `dark` for navy sections; `light` for white sections. */
  tone?: "dark" | "light";
  className?: string;
};

/** Horizontal band of headline metrics (impressions, leads, creators, match). */
export function StatStrip({ stats, tone = "light", className }: StatStripProps) {
  const dark = tone === "dark";
  return (
    <section
      className={
        dark
          ? `bg-navy py-16 text-white ${className ?? ""}`
          : `bg-white py-16 ${className ?? ""}`
      }
    >
      <Container>
        <dl className="grid grid-cols-2 gap-x-6 gap-y-10 text-center md:grid-cols-4">
          {stats.map((stat) => (
            <div key={stat.label} className="flex flex-col items-center gap-2">
              <dt
                className={
                  dark
                    ? "order-2 text-sm font-medium text-white/60"
                    : "order-2 text-sm font-medium text-muted-foreground"
                }
              >
                {stat.label}
              </dt>
              <dd className="order-1 text-4xl font-extrabold tracking-tight sm:text-5xl">
                <span className={dark ? "text-white" : "text-gradient"}>
                  {stat.value}
                </span>
              </dd>
            </div>
          ))}
        </dl>
      </Container>
    </section>
  );
}

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import { Container } from "@/components/ui/container";
import { SectionHeading } from "@/components/ui/section-heading";

export type FeatureStep = {
  title: string;
  description: string;
  /** Optional icon (lucide component element). */
  icon?: ReactNode;
  /** Optional illustrative content rendered inside the card (e.g. status chips). */
  visual?: ReactNode;
};

type FeatureStepsProps = {
  eyebrow?: string;
  heading?: ReactNode;
  subheading?: ReactNode;
  steps: FeatureStep[];
  /** Show 1..N numbers on each step. */
  numbered?: boolean;
  /** Grid columns at the lg breakpoint. */
  columns?: 2 | 3;
  className?: string;
};

/**
 * A numbered / iconed grid of product steps. Used for the homepage
 * "One platform, from brief to results" and the How it works timeline.
 */
export function FeatureSteps({
  eyebrow,
  heading,
  subheading,
  steps,
  numbered = false,
  columns = 3,
  className,
}: FeatureStepsProps) {
  return (
    <section className={cn("bg-white py-20 sm:py-24", className)}>
      <Container>
        {(heading || eyebrow || subheading) && (
          <SectionHeading
            eyebrow={eyebrow}
            title={heading}
            subtitle={subheading}
            className="mx-auto mb-14"
          />
        )}
        <ol
          className={cn(
            "grid gap-6",
            columns === 2 ? "sm:grid-cols-2" : "sm:grid-cols-2 lg:grid-cols-3",
          )}
        >
          {steps.map((step, i) => (
            <li
              key={step.title}
              className="group relative flex flex-col rounded-2xl border border-border bg-white p-6 shadow-sm transition-all hover:-translate-y-1 hover:border-brand/30 hover:shadow-md"
            >
              <div className="flex items-center gap-3">
                {numbered && (
                  <span className="inline-flex size-9 shrink-0 items-center justify-center rounded-full bg-ink text-sm font-bold text-white">
                    {i + 1}
                  </span>
                )}
                {step.icon && (
                  <span className="inline-flex size-9 shrink-0 items-center justify-center rounded-xl bg-brand/10 text-brand-700">
                    {step.icon}
                  </span>
                )}
              </div>
              <h3 className="mt-4 text-lg font-semibold tracking-tight text-foreground">
                {step.title}
              </h3>
              <p className="mt-2 text-sm leading-relaxed text-muted-foreground">
                {step.description}
              </p>
              {step.visual && <div className="mt-5">{step.visual}</div>}
            </li>
          ))}
        </ol>
      </Container>
    </section>
  );
}

import { Container } from "@/components/ui/container";
import { SectionHeading } from "@/components/ui/section-heading";

export type FaqItem = { question: string; answer: string };

type FaqProps = {
  eyebrow?: string;
  heading?: string;
  subheading?: string;
  items: FaqItem[];
  className?: string;
};

/**
 * Accordion FAQ built on native <details>/<summary> so it works without
 * client JS (progressive enhancement, accessible by default).
 */
export function Faq({
  eyebrow = "FAQ",
  heading = "Frequently asked questions",
  subheading,
  items,
  className,
}: FaqProps) {
  return (
    <section className={`bg-muted/30 py-20 sm:py-24 ${className ?? ""}`}>
      <Container>
        <SectionHeading
          eyebrow={eyebrow}
          title={heading}
          subtitle={subheading}
          className="mx-auto mb-12"
        />
        <div className="mx-auto max-w-3xl divide-y divide-border overflow-hidden rounded-2xl border border-border bg-white">
          {items.map((item) => (
            <details key={item.question} className="group">
              <summary className="flex cursor-pointer list-none items-center justify-between gap-4 px-6 py-5 text-left font-semibold text-foreground transition-colors hover:bg-muted/50 [&::-webkit-details-marker]:hidden">
                <span>{item.question}</span>
                <svg
                  aria-hidden
                  viewBox="0 0 24 24"
                  className="size-5 shrink-0 text-muted-foreground transition-transform duration-200 group-open:rotate-45"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                >
                  <path d="M12 5v14M5 12h14" />
                </svg>
              </summary>
              <div className="px-6 pb-6 text-sm leading-relaxed text-muted-foreground">
                {item.answer}
              </div>
            </details>
          ))}
        </div>
      </Container>
    </section>
  );
}

import type { ReactNode } from "react";
import { Container } from "@/components/ui/container";
import { SectionHeading } from "@/components/ui/section-heading";
import { Avatar } from "@/components/ui/avatar";

type CaseStat = { value: string; label: string };

type TestimonialProps = {
  eyebrow?: string;
  heading?: ReactNode;
  quote: string;
  authorName: string;
  authorRole: string;
  /** Optional mini case-study stats shown alongside the quote. */
  caseStats?: CaseStat[];
  caseLabel?: ReactNode;
};

/** Featured customer quote with an optional mini case-study stat block. */
export function Testimonial({
  eyebrow,
  heading,
  quote,
  authorName,
  authorRole,
  caseStats,
  caseLabel,
}: TestimonialProps) {
  return (
    <section className="bg-white py-20 sm:py-24">
      <Container>
        {(heading || eyebrow) && (
          <SectionHeading
            eyebrow={eyebrow}
            title={heading}
            className="mx-auto mb-14"
          />
        )}
        <div className="mx-auto grid max-w-5xl items-stretch gap-6 lg:grid-cols-5">
          {/* Quote card */}
          <figure className="relative flex flex-col justify-between rounded-3xl bg-navy p-8 text-white shadow-sm sm:p-10 lg:col-span-3">
            <span
              aria-hidden
              className="text-6xl font-serif leading-none text-white/20"
            >
              &ldquo;
            </span>
            <blockquote className="-mt-4 text-pretty text-xl font-medium leading-snug sm:text-2xl">
              {quote}
            </blockquote>
            <figcaption className="mt-8 flex items-center gap-3">
              <Avatar name={authorName} />
              <div>
                <div className="font-semibold">{authorName}</div>
                <div className="text-sm text-white/60">{authorRole}</div>
              </div>
            </figcaption>
          </figure>

          {/* Case-study stat block */}
          {caseStats && caseStats.length > 0 && (
            <div className="flex flex-col rounded-3xl border border-border bg-muted/30 p-8 lg:col-span-2">
              {caseLabel && (
                <p className="text-xs font-semibold uppercase tracking-widest text-brand">
                  {caseLabel}
                </p>
              )}
              <dl className="mt-4 grid grid-cols-2 gap-6">
                {caseStats.map((stat) => (
                  <div key={stat.label}>
                    <dd className="text-2xl font-extrabold tracking-tight text-foreground sm:text-3xl">
                      {stat.value}
                    </dd>
                    <dt className="mt-1 text-sm text-muted-foreground">
                      {stat.label}
                    </dt>
                  </div>
                ))}
              </dl>
            </div>
          )}
        </div>
      </Container>
    </section>
  );
}

